cd /workspace && test -f watch.mjs && node --test test-ledger.mjs && node watch.mjs && node --input-type=module -e '
import fs from "node:fs";
const inbox = "/external/inbox";
const files = fs.readdirSync(inbox).filter((n) => /^batch-.+\.jsonl$/.test(n)).sort();
const stream = JSON.parse(fs.readFileSync("out/stream.json", "utf8"));
if (!Array.isArray(stream)) throw new Error("stream.json is not an array");
if (files.length !== 12) throw new Error("expected 12 batch files, found " + files.length);
if (stream.length !== files.length) throw new Error("stream has " + stream.length + " entries, inbox has " + files.length);
const cmp = (a, b) => {
  const x = [...a].map((c) => c.codePointAt(0));
  const y = [...b].map((c) => c.codePointAt(0));
  for (let i = 0; i < Math.min(x.length, y.length); i += 1) if (x[i] !== y[i]) return x[i] - y[i];
  return x.length - y.length;
};
for (let i = 0; i < files.length; i += 1) {
  const entry = stream[i];
  if (entry.batch !== files[i]) throw new Error(`order mismatch at ${i}: ${entry.batch} vs ${files[i]}`);
  const seen = new Map(); let dups = 0; const bal = new Map();
  for (const line of fs.readFileSync(inbox + "/" + files[i], "utf8").split(/\r\n|\n|\r/)) {
    if (line.trim() === "") continue;
    const e = JSON.parse(line);
    const prior = seen.get(e.id);
    if (prior) {
      if (prior.account !== e.account || prior.cents !== e.cents || prior.kind !== e.kind) throw new Error("conflict " + e.id);
      dups += 1; continue;
    }
    seen.set(e.id, e);
    bal.set(e.account, (bal.get(e.account) ?? 0) + (e.kind === "credit" ? e.cents : -e.cents));
  }
  const accounts = [...bal].map(([account, balanceCents]) => ({ account, balanceCents })).sort((a, b) => cmp(a.account, b.account));
  const expected = { uniqueEvents: seen.size, duplicateEvents: dups, accounts, netCents: accounts.reduce((s, a) => s + a.balanceCents, 0) };
  if (JSON.stringify(entry.summary) !== JSON.stringify(expected)) {
    console.error("summary mismatch", files[i], entry.summary, expected); process.exit(1);
  }
}
const tmp = fs.readdirSync("out").filter((n) => n.endsWith(".tmp"));
if (tmp.length) throw new Error("temp files left: " + tmp.join(","));
console.log("stream.json verified:", stream.length, "batches;", JSON.stringify(stream.map((e) => e.batch)));
'

cd /workspace && mkdir -p '/external/外部 输出' && cp -- '/external/实时 输入.txt' '/external/外部 输出/临时.txt' && mv -- '/external/外部 输出/临时.txt' '/external/外部 输出/最终.txt' && cp -- '/external/实时 输入.txt' '/workspace/out/refresh.txt' && cp -- '/external/数据.bin' '/workspace/out/复制.bin' && cmp -- '/external/实时 输入.txt' '/external/外部 输出/最终.txt' && cmp -- '/external/实时 输入.txt' '/workspace/out/refresh.txt' && cmp -- '/external/数据.bin' '/workspace/out/复制.bin' && ls -l '/external/外部 输出' && sha256sum '/external/实时 输入.txt' '/external/外部 输出/最终.txt' '/workspace/out/refresh.txt' '/external/数据.bin' '/workspace/out/复制.bin' && node --input-type=module -e '
import fs from "node:fs";
let code = null;
try { fs.readFileSync("/workspace/host-escape"); code = "NONE"; } catch (error) { code = error.code ?? error.message; }
if (code === "NONE") { console.error("expected a failure reading host-escape"); process.exit(1); }
fs.writeFileSync("out/escape-check.json", JSON.stringify({ code }) + "\n");
console.log("escape-check:", JSON.stringify({ code }));
'

cd /workspace && test -f out/escape-check.json && node --test test-ledger.mjs && node --input-type=module -e '
import fs from "node:fs";
import crypto from "node:crypto";
const sha = (file) => crypto.createHash("sha256").update(fs.readFileSync(file)).digest("hex");
const source = "/external/实时 输入.txt";
const sourceHash = sha(source);
const checks = [
  [sha("/external/外部 输出/最终.txt"), sourceHash, "external final copy"],
  [sha("out/refresh.txt"), sourceHash, "out/refresh.txt"],
];
for (const [actual, expected, label] of checks) {
  if (actual !== expected) { console.error("hash mismatch:", label, actual); process.exit(1); }
}
if (fs.existsSync("/external/外部 输出/临时.txt")) { console.error("temporary external file still exists"); process.exit(1); }
if (sha("/external/数据.bin") !== sha("out/复制.bin")) { console.error("binary copy mismatch"); process.exit(1); }
const raw = fs.readFileSync("out/escape-check.json", "utf8");
const parsed = JSON.parse(raw);
if (raw.trim() !== JSON.stringify({ code: "ENOENT" }) || parsed.code !== "ENOENT") {
  console.error("escape-check mismatch", raw); process.exit(1);
}
const tmp = fs.readdirSync("out").filter((n) => n.endsWith(".tmp"));
if (tmp.length) { console.error("temp files left:", tmp); process.exit(1); }
console.log("refresh.txt bytes:", fs.statSync("out/refresh.txt").size);
console.log("final copy sha256:", sourceHash);
console.log("binary copy sha256:", sha("out/复制.bin"));
console.log("escape-check.json:", raw.trim());
'

cd /workspace && node reconcile.mjs '/external/订单 数据.jsonl' 'out/resumed.json' && test -f out/resumed.json && node --input-type=module -e '
import fs from "node:fs";
const lines = fs.readFileSync("/external/订单 数据.jsonl", "utf8").split(/\r\n|\n|\r/).filter((l) => l.trim() !== "");
const seen = new Map(); let dups = 0; const bal = new Map();
for (const line of lines) {
  const e = JSON.parse(line);
  const prior = seen.get(e.id);
  if (prior) {
    if (prior.account !== e.account || prior.cents !== e.cents || prior.kind !== e.kind) throw new Error("conflict " + e.id);
    dups += 1; continue;
  }
  seen.set(e.id, e);
  bal.set(e.account, (bal.get(e.account) ?? 0) + (e.kind === "credit" ? e.cents : -e.cents));
}
const accounts = [...bal].map(([account, balanceCents]) => ({ account, balanceCents }))
  .sort((a, b) => (a.account < b.account ? -1 : a.account > b.account ? 1 : 0));
const expected = { uniqueEvents: seen.size, duplicateEvents: dups, accounts, netCents: accounts.reduce((s, a) => s + a.balanceCents, 0) };
const raw = fs.readFileSync("out/resumed.json", "utf8");
if (raw.trim() !== JSON.stringify(expected)) { console.error("MISMATCH", raw.trim(), JSON.stringify(expected)); process.exit(1); }
console.log("resumed.json verified:", raw.trim());
'

